INSERT INTO feature VALUES('rule-equations','rules','Rules as equations (<=>)','presented-types','implemented','notable',NULL,'`rule l <=> r` states an equation and the path order chooses its direction, `==>` pinning one. An effect theory''s rule, as oriented, also rewrites the subject of a scope over the theory before it runs (`effect-theories`).','surface-lowering','corpus/model/data/rule-equation.gandr corpus/pathological/data/rule-equation-unoriented.gandr corpus/model/effects/state-laws.gandr','corpus/ledger/features/rule-equations.gandr',NULL);
